mapper.select:
		 select  a.ORGNAME as ImpLssuedUnitName,t.REALNAME as ImpLssuedStaffidName,r.* from TBL_RISK_IMPLEMENT r 

        left join TBL_ORGANIZATION a on  r.IMP_LSSUED_UNIT=a.ORGID  
        left join TBL_STAFF t on r.IMP_LSSUED_STAFFID=t.STAFFID where 1=1  

			and IMP_RISK_NAME  LIKE concat(concat('%',#{queryParam.impRiskName} ),'%')


			and majorId=#{queryParam.majorId}


	        and id in 

	      #{item}	   



			  and ( IMP_LSSUED_STAFFID=#{queryParam.impLssuedStaffid} or TRANSFERSTAFFID=#{queryParam.impLssuedStaffid})


			  and IMP_LSSUED_UNIT=#{queryParam.impLssuedUnit}


		order by id

select c.QUARTERNAME as jd,c.RISKYEAR as nd,a.ORGNAME as ImpLssuedUnitName ,t.REALNAME as ImpLssuedStaffidName,r.* from TBL_RISK_IMPLEMENT r left join TBL_MAJORRISK_BRANCHCREATE c on c.id=r.majorId left join TBL_ORGANIZATION a on r.IMP_LSSUED_UNIT=a.ORGID left join TBL_STAFF t on r.IMP_LSSUED_STAFFID=t.STAFFID where 1=1 and r.toreport=1
and IMP_RISK_NAME =#{impRiskName}
order by imp_risk_name,id desc
